// Skynet CTF's live Worker entry point — a Cloudflare Worker with static
// assets (see wrangler.toml), not Pages. Answer hashes and checking logic
// live only here, not in the browser, so view-source can't be a free
// answer oracle, though it doesn't stop client-side state tampering (e.g. localStorage).

// The only copy of each node's answer hash (NODES[] in console.js has
// none) — regenerate here, never hand-type, if an answer changes. `deco`
// hashes the deco-bonus cipher's plaintext, not the fragments.
const ANSWER_HASHES = {
  n1: "e43781640b80cf82007d12b66a5611931ad569166b98543e9ffd0d727462a126",
  n2: "28e211aeed4eb2e1740d7da242b4b34c676875b2691ccb247761ae87f2bd1b2e",
  n3: "19a1c2633ba1fcaf4bd787dd32afc50fb9deb40ea39c3c4e27636773b30eb2bc",
  n4: "3c8036d705a7273ebcb331091e1abf38933a33aad554909ef732b9c5a7d15191",
  n5: "a84e88d513f0e08ab9825defffc00eb7e67119c1f4d57f45be342707396dd14b",
  n6: "10c08ff84069d1ed0f8ff2622ac710954df7260a1c7cb38c983c35a4208a6511",
  n7: "f55de374352faf2a5136a98a91c092fd290a7366c1838bc3d1819937491f0cb1",
  // b1's answer text (JCTSIH -> JCRAIA) changed alongside a CORE-hardening
  // pass — see GLYPH_CIPHERTEXTS.b1's comment; n7's hash is unaffected.
  b1: "a4ac5addb4d57b6b1ec0d1d934acb6119397dcb75adca89b3c73d73fec2d5273",
  deco: "3a21a6e6253dafbb08f466c04123ef5b92df9c12e4f50d4b50516995acc3b528",
};

// index.html's gate phrase — used to be a bare plaintext constant in
// gate.js, checked client-side. Kept separate from ANSWER_HASHES since
// this isn't a real node and doesn't belong in NODES[]/CHAIN.
const GATE_ANSWER_HASH = "e6e2964b5776fe6a1d4ae56e9e20826b47c4dc90c6e7ccec68577b8fbf0c0533";

// Extra payload returned only alongside a correct answer for the given id
// (opt-in per id) — keeps the deco bonus's reward off the client until
// it's genuinely earned, unlike n1-n7/b1 which just get bare {correct}.
const REWARDS = {
  deco: "CRYSTAL_PEAK // SHELTER-03 // STILL LISTENING",
};

// NODE_04/NODE_05 light-touch hints — same opt-in-on-correct-answer
// treatment as REWARDS, keyed by the submitted id ("deco") since both
// hints ride along with that one unlock event. Confirms cipher
// family/key location without doing the solving.
const HINTS = {
  deco: {
    n4: "Two arms, eight positions each. Sailors used this before radios existed — look up flag semaphore, not Morse.",
    n5: "The key was never hidden. It was announced, in the first transmission's header, disguised as a timestamp — not all of it. Just the part that isn't a date.",
  },
};

// Must match normalizeAnswer() in scripts/console.js byte-for-byte, or a
// guess accepted client-side could be rejected here (or vice versa).
function normalizeAnswer(s) {
  return s
    .trim()
    .toLowerCase()
    .replace(/^flag\{(.*)\}$/, "$1")
    .replace(/['".,!?]/g, "")
    .replace(/[-_\s]+/g, " ")
    .trim();
}

// Real Web Crypto, unlike console.js's hand-rolled sha256Hex (which exists
// only because crypto.subtle throws outside a secure context, i.e. on
// file://) — a Worker always runs in a secure context.
async function sha256Hex(str) {
  const bytes = new TextEncoder().encode(str);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// Fixed-window per-IP counter in KV, one independent bucket per use —
// "glyph"/"nodeCipher"/"audio" are generous since they aren't real
// secret-guessing oracles, while "answer"/"fragment"/"gate"/"gateQr" stay
// tight. Delay-not-block friction, not a hard boundary — KV is only
// eventually consistent, so a burst of requests can slip over the limit.
const RATE_LIMITS = {
  answer: { limit: 5, windowS: 60 },
  glyph: { limit: 60, windowS: 60 },
  fragment: { limit: 6, windowS: 60 },
  nodeCipher: { limit: 30, windowS: 60 },
  audio: { limit: 10, windowS: 60 },
  // Solving the actual Turnstile challenge is the real bottleneck here,
  // not this bucket — generous enough that apiFetch()'s single
  // retry-on-401 never fights it during ordinary use.
  turnstileVerify: { limit: 10, windowS: 60 },
  // A bit more generous than `answer` since a blind-typed two-word phrase
  // draws more real typos than a considered node-answer submission.
  gate: { limit: 8, windowS: 60 },
  // Same tier as `gate`, not the more generous nodeCipher/audio numbers —
  // this response alone fully determines the gate phrase once decoded.
  gateQr: { limit: 8, windowS: 60 },
};

// `ctx.waitUntil()` lets the KV write happen in the background instead of
// making every gated request pay for a sequential get+put before
// responding — the put only needs to land before the next request in the
// window. Falls back to awaiting in place if `ctx` is missing.
function putRateLimitState(kv, key, value, keyTtlS, ctx) {
  const write = kv.put(key, JSON.stringify(value), { expirationTtl: keyTtlS });
  if (ctx) ctx.waitUntil(write);
  else return write; // no ctx available — fall back to blocking on it, same as before
}

async function checkRateLimit(kv, bucket, ip, ctx) {
  const { limit, windowS } = RATE_LIMITS[bucket];
  const keyTtlS = windowS + 10; // outlives the window slightly so a read right at expiry doesn't race a just-vanished key
  const key = `rl:${bucket}:${ip}`;
  const now = Date.now();
  const raw = await kv.get(key);
  const state = raw ? JSON.parse(raw) : null;

  if (!state || now - state.windowStart > windowS * 1000) {
    await putRateLimitState(kv, key, { windowStart: now, count: 1 }, keyTtlS, ctx);
    return { limited: false };
  }

  if (state.count >= limit) {
    const retryAfter = Math.ceil((state.windowStart + windowS * 1000 - now) / 1000);
    return { limited: true, retryAfter };
  }

  await putRateLimitState(kv, key, { windowStart: state.windowStart, count: state.count + 1 }, keyTtlS, ctx);
  return { limited: false };
}

function json(body, status) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

// Turnstile + session-token gate — closes raw, unauthenticated POST access
// to every handler below; requireSession() is what each one checks first.
const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder();

function bytesToBase64Url(bytes) {
  let binary = "";
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function base64UrlToBytes(str) {
  const padded = str.replace(/-/g, "+").replace(/_/g, "/");
  const pad = padded.length % 4 === 0 ? "" : "=".repeat(4 - (padded.length % 4));
  const binary = atob(padded + pad);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

async function hmacKey(secret) {
  return crypto.subtle.importKey(
    "raw",
    textEncoder.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"]
  );
}

// 4 hours — comfortably covers a real solve session without forcing a
// mid-run Turnstile re-solve.
const SESSION_TOKEN_TTL_MS = 4 * 60 * 60 * 1000;

// base64url(JSON payload) + "." + base64url(HMAC-SHA256 of those bytes) —
// not a JWT (no header/alg negotiation needed for one closed verifier).
async function mintSessionToken(env) {
  const exp = Date.now() + SESSION_TOKEN_TTL_MS;
  const payloadBytes = textEncoder.encode(JSON.stringify({ exp }));
  const key = await hmacKey(env.SESSION_SIGNING_SECRET);
  const sig = await crypto.subtle.sign("HMAC", key, payloadBytes);
  const token = `${bytesToBase64Url(payloadBytes)}.${bytesToBase64Url(new Uint8Array(sig))}`;
  return { token, exp };
}

async function verifySessionToken(token, env) {
  if (typeof token !== "string") return false;
  const parts = token.split(".");
  if (parts.length !== 2) return false;
  let payloadBytes, sigBytes;
  try {
    payloadBytes = base64UrlToBytes(parts[0]);
    sigBytes = base64UrlToBytes(parts[1]);
  } catch {
    return false; // malformed base64url — not a token this Worker ever issued
  }
  const key = await hmacKey(env.SESSION_SIGNING_SECRET);
  const validSig = await crypto.subtle.verify("HMAC", key, sigBytes, payloadBytes);
  if (!validSig) return false;
  let payload;
  try {
    payload = JSON.parse(textDecoder.decode(payloadBytes));
  } catch {
    return false;
  }
  return typeof payload.exp === "number" && Date.now() < payload.exp;
}

async function requireSession(request, env) {
  // Fails OPEN if the secret isn't configured yet — a fresh deploy without
  // it should mean "this gate doesn't exist yet," not a broken site.
  // Verify enforcement with a curl call missing the header; it should 401
  // once SESSION_SIGNING_SECRET is actually set.
  if (!env.SESSION_SIGNING_SECRET) return true;
  return verifySessionToken(request.headers.get("X-Session-Token"), env);
}

const TURNSTILE_VERIFY_URL = "https://challenges.cloudflare.com/turnstile/v0/siteverify";

async function handleVerifyTurnstile(request, env, ctx) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "bad_request" }, 400);
  }

  const { token } = body || {};
  if (typeof token !== "string" || !token) {
    return json({ error: "bad_request" }, 400);
  }

  if (!env.TURNSTILE_SECRET_KEY || !env.SESSION_SIGNING_SECRET) {
    // A clear, specific failure here beats letting this fall through to a
    // vaguer rejection from Cloudflare's siteverify API — this is a
    // deploy-config problem, not a player-facing one.
    return json({ error: "turnstile_not_configured" }, 500);
  }

  if (env.RATE_LIMIT) {
    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    const { limited, retryAfter } = await checkRateLimit(env.RATE_LIMIT, "turnstileVerify", ip, ctx);
    if (limited) {
      return json({ error: "rate_limited", retryAfter }, 429);
    }
  }

  const ip = request.headers.get("CF-Connecting-IP") || "unknown";
  let verifyResult;
  try {
    const verifyRes = await fetch(TURNSTILE_VERIFY_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ secret: env.TURNSTILE_SECRET_KEY, response: token, remoteip: ip }),
    });
    verifyResult = await verifyRes.json();
  } catch {
    return json({ error: "turnstile_unreachable" }, 502);
  }

  if (!verifyResult.success) {
    return json({ error: "turnstile_failed" }, 403);
  }

  const { token: sessionToken, exp } = await mintSessionToken(env);
  return json({ sessionToken, exp }, 200);
}

async function handleCheckAnswer(request, env, ctx) {
  // Session check first, before parsing the body — every gated handler
  // below does the same check in the same spot.
  if (!(await requireSession(request, env))) {
    return json({ error: "unauthorized" }, 401);
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "bad_request" }, 400);
  }

  const { nodeId, guess } = body || {};
  // Length cap is just input hygiene — the rate limiter below is the real anti-abuse measure.
  if (typeof nodeId !== "string" || typeof guess !== "string" || guess.length > 200) {
    return json({ error: "bad_request" }, 400);
  }
  if (!(nodeId in ANSWER_HASHES)) {
    return json({ error: "unknown_node" }, 404);
  }

  // Missing KV binding fails safe (always allow) rather than crashing
  // every guess.
  if (env.RATE_LIMIT) {
    // Set by Cloudflare itself at the edge — a client can't override it.
    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    const { limited, retryAfter } = await checkRateLimit(env.RATE_LIMIT, "answer", ip, ctx);
    if (limited) {
      return json({ error: "rate_limited", retryAfter }, 429);
    }
  }

  const hash = await sha256Hex(normalizeAnswer(guess));
  const correct = hash === ANSWER_HASHES[nodeId];
  // REWARDS/HINTS are opt-in per id — ids without either just get {correct} below.
  if (correct && (nodeId in REWARDS || nodeId in HINTS)) {
    const body = { correct: true };
    if (nodeId in REWARDS) body.reward = REWARDS[nodeId];
    if (nodeId in HINTS) body.hints = HINTS[nodeId];
    return json(body, 200);
  }
  return json({ correct }, 200);
}

// index.html's gate check — deliberately NOT behind requireSession() like
// the console.html-side endpoints. This is the front door protecting one
// static phrase that never rotates, so a rate limit alone is proportionate.
async function handleCheckGate(request, env, ctx) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "bad_request" }, 400);
  }

  const { guess } = body || {};
  if (typeof guess !== "string" || guess.length > 200) {
    return json({ error: "bad_request" }, 400);
  }

  if (env.RATE_LIMIT) {
    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    const { limited, retryAfter } = await checkRateLimit(env.RATE_LIMIT, "gate", ip, ctx);
    if (limited) {
      return json({ error: "rate_limited", retryAfter }, 429);
    }
  }

  const hash = await sha256Hex(normalizeAnswer(guess));
  return json({ correct: hash === GATE_ANSWER_HASH }, 200);
}

// A second, near-invisible discovery channel for the gate phrase: a QR
// code encoding "No Fate", rendered by scripts/gate.js — must live
// server-side since a QR grid is itself the fully-decoded payload. One
// row per string, "1" = dark module, "0" = light; the quiet zone a
// scanner needs is added at render time, not baked in here.
const GATE_QR_MODULES = [
  "111111100100001111111",
  "100000101101001000001",
  "101110100110101011101",
  "101110100100101011101",
  "101110100100101011101",
  "100000101011001000001",
  "111111101010101111111",
  "000000001100100000000",
  "000011110000101100010",
  "010001011100110001010",
  "011110111100101110110",
  "010011011100101011001",
  "110011101010010100000",
  "000000001111001010111",
  "111111101010001011010",
  "100000101000101110011",
  "101110101010000100101",
  "101110100110100111111",
  "101110100101010011100",
  "100000100101111010000",
  "111111100100110000001",
];

// Not behind requireSession(), same reasoning as handleCheckGate — this is
// the front door. Rate-limited at `gate`'s tier since the response fully
// determines the phrase the moment it's decoded.
async function handleGateQr(request, env, ctx) {
  if (env.RATE_LIMIT) {
    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    const { limited, retryAfter } = await checkRateLimit(env.RATE_LIMIT, "gateQr", ip, ctx);
    if (limited) {
      return json({ error: "rate_limited", retryAfter }, 429);
    }
  }

  return json({ size: GATE_QR_MODULES.length, rows: GATE_QR_MODULES }, 200);
}

// Seeds the CORE-glyph alphabet's daily rotation (see console.js's
// buildGlyphCipher comment). The mapping is recomputed fresh per request
// from this salt + today's UTC date, never stored, so a leaked mapping
// expires at the next UTC midnight instead of staying valid forever.
const GLYPH_ROTATION_SALT = "84484de362a53f376e012bf019603fbf4cea89e35a52b60e";

// UTC, not local time — the same "today" for every visitor and edge location.
function todayDateString() {
  return new Date().toISOString().slice(0, 10); // "YYYY-MM-DD"
}

// A small, fast, deterministic PRNG seeded from one 32-bit integer — not
// cryptographically secure, but only the seed (via GLYPH_ROTATION_SALT)
// needs to stay unpredictable, not the algorithm itself.
function mulberry32(seed) {
  return function () {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Deterministically shuffles the 26-letter alphabet for "today" — same
// output for every request on a given UTC date. Recomputed fresh each
// call rather than cached, since Workers don't guarantee module-scope
// state survives between requests.
async function todayGlyphLetters() {
  const seedHex = await sha256Hex(GLYPH_ROTATION_SALT + ":" + todayDateString());
  const rng = mulberry32(parseInt(seedHex.slice(0, 8), 16));
  const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");
  // Fisher-Yates, using the seeded rng instead of Math.random so the
  // result is reproducible for a given seed rather than different on
  // every call.
  for (let i = letters.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [letters[i], letters[j]] = [letters[j], letters[i]];
  }
  return letters.join("");
}

async function handleRevealGlyph(request, env, ctx) {
  if (!(await requireSession(request, env))) {
    return json({ error: "unauthorized" }, 401);
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "bad_request" }, 400);
  }

  const { index } = body || {};
  if (!Number.isInteger(index) || index < 0 || index >= 26) {
    return json({ error: "bad_request" }, 400);
  }

  // Fails safe (unthrottled) if the binding is misconfigured.
  if (env.RATE_LIMIT) {
    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    const { limited, retryAfter } = await checkRateLimit(env.RATE_LIMIT, "glyph", ip, ctx);
    if (limited) {
      return json({ error: "rate_limited", retryAfter }, 429);
    }
  }

  const todayLetters = await todayGlyphLetters();
  return json({ letter: todayLetters[index] }, 200);
}

// The rotation-independent ciphertext behind every glyph-cipher surface;
// handleNodeCipher combines it with today's rotated alphabet per request.
// b1 is Atbash(Vigenère(plaintext, REWARDS.deco-derived key)) and its
// plaintext hands the player CORE (n7)'s key — keep in sync with n7's key
// derivation in console.js.
const GLYPH_CIPHERTEXTS = {
  n1: "WHQTRZRAG QNL",
  n3: "TES TON SI ERUTUF EHT",
  // Same Vigenère ciphertext n5 has always used, just glyph-rendered —
  // the cipher, answer, and ANSWER_HASHES.n5 are unchanged.
  n5: "IV DENV CI BCSKAKOID YJXH KU GAPU FE TFESQOID YJXH",
  deco: "VYCJX ACT STRWYW",
  b1: "GUNO WVQ BTIPZS",
};

async function handleNodeCipher(request, env, ctx) {
  if (!(await requireSession(request, env))) {
    return json({ error: "unauthorized" }, 401);
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "bad_request" }, 400);
  }

  const { key } = body || {};
  if (typeof key !== "string" || !(key in GLYPH_CIPHERTEXTS)) {
    return json({ error: "bad_request" }, 400);
  }

  // Light-touch limit — hands back which glyph shape to draw, not what it
  // means, so this isn't really a secret-guessing oracle.
  if (env.RATE_LIMIT) {
    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    const { limited, retryAfter } = await checkRateLimit(env.RATE_LIMIT, "nodeCipher", ip, ctx);
    if (limited) {
      return json({ error: "rate_limited", retryAfter }, 429);
    }
  }

  const todayLetters = await todayGlyphLetters();
  const ciphertext = GLYPH_CIPHERTEXTS[key];
  const indices = [...ciphertext].map((ch) => (ch === " " ? null : todayLetters.indexOf(ch)));
  return json({ indices }, 200);
}

// The 4 decorative-node fragment strings, revealed one at a time via
// handleRevealFragment rather than shipped in console.js source. Keys
// must match DECO_NODES' own ids there — update both together.
const DECO_FRAGMENTS = {
  d1: "CRYSTAL",
  d2: "PEAK",
  d3: "SHELTER",
  d4: "THREE",
};

async function handleRevealFragment(request, env, ctx) {
  if (!(await requireSession(request, env))) {
    return json({ error: "unauthorized" }, 401);
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "bad_request" }, 400);
  }

  const { decoId } = body || {};
  if (typeof decoId !== "string" || !(decoId in DECO_FRAGMENTS)) {
    return json({ error: "bad_request" }, 400);
  }

  // Fails safe (unthrottled) if the binding is misconfigured.
  if (env.RATE_LIMIT) {
    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    const { limited, retryAfter } = await checkRateLimit(env.RATE_LIMIT, "fragment", ip, ctx);
    if (limited) {
      return json({ error: "rate_limited", retryAfter }, 429);
    }
  }

  return json({ fragment: DECO_FRAGMENTS[decoId] }, 200);
}

// NODE_02's cipher audio (a spectrogram-encoded, Atbash-shifted message —
// see console.js), base64-encoded here instead of served as a plain
// static file. Regenerate by re-encoding and diffing byte-for-byte against
// the original if this audio ever changes; don't hand-type it.
const NODE_AUDIO = {
  n2: "",
};

async function handleNodeAudio(request, env, ctx) {
  if (!(await requireSession(request, env))) {
    return json({ error: "unauthorized" }, 401);
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "bad_request" }, 400);
  }

  const { key } = body || {};
  if (typeof key !== "string" || !(key in NODE_AUDIO)) {
    return json({ error: "bad_request" }, 400);
  }

  // Fails safe (unthrottled) if the binding is misconfigured.
  if (env.RATE_LIMIT) {
    const ip = request.headers.get("CF-Connecting-IP") || "unknown";
    const { limited, retryAfter } = await checkRateLimit(env.RATE_LIMIT, "audio", ip, ctx);
    if (limited) {
      return json({ error: "rate_limited", retryAfter }, 429);
    }
  }

  // Raw binary rather than JSON — wrapping a 600KB+ payload in base64-inside-JSON would just inflate it further.
  const binary = atob(NODE_AUDIO[key]);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Response(bytes, {
    status: 200,
    headers: { "Content-Type": "audio/wav" },
  });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (request.method === "POST" && url.pathname === "/check-answer") {
      return handleCheckAnswer(request, env, ctx);
    }
    if (request.method === "POST" && url.pathname === "/reveal-glyph") {
      return handleRevealGlyph(request, env, ctx);
    }
    if (request.method === "POST" && url.pathname === "/reveal-fragment") {
      return handleRevealFragment(request, env, ctx);
    }
    if (request.method === "POST" && url.pathname === "/node-cipher") {
      return handleNodeCipher(request, env, ctx);
    }
    if (request.method === "POST" && url.pathname === "/node-audio") {
      return handleNodeAudio(request, env, ctx);
    }
    if (request.method === "POST" && url.pathname === "/verify-turnstile") {
      return handleVerifyTurnstile(request, env, ctx);
    }
    if (request.method === "POST" && url.pathname === "/check-gate") {
      return handleCheckGate(request, env, ctx);
    }
    if (request.method === "POST" && url.pathname === "/gate-qr") {
      return handleGateQr(request, env, ctx);
    }
    // Everything else falls through to the static-asset binding.
    return env.ASSETS.fetch(request);
  },
};
